import{_ as n,o as s,c as a,a as t}from"./app-631b6948.js";const o={},p=t(`<h1 id="protocols" tabindex="-1"><a class="header-anchor" href="#protocols" aria-hidden="true">#</a> Protocols</h1><p>A <code>protocol</code> describes a set of methods without choosing a concrete object type. It lets you write code in terms of behavior instead of a specific implementation.</p><h2 id="declaring-a-protocol" tabindex="-1"><a class="header-anchor" href="#declaring-a-protocol" aria-hidden="true">#</a> Declaring a protocol</h2><p>Declare a protocol with one or more method signatures:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">protocol</span> <span class="token class-name">Translatable</span> <span class="token punctuation">{</span>
    <span class="token keyword">mut</span> <span class="token keyword">fun</span> <span class="token function-definition function">translate</span><span class="token punctuation">(</span>dx<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">,</span> dy<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">protocol</span> <span class="token class-name">Printable</span> <span class="token punctuation">{</span>
    <span class="token keyword">fun</span> <span class="token function-definition function">print</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The protocol only defines the required methods. It does not declare fields or method bodies.</p><h2 id="conforming-to-protocols" tabindex="-1"><a class="header-anchor" href="#conforming-to-protocols" aria-hidden="true">#</a> Conforming to protocols</h2><p>An object can conform to any number of protocols by listing them after <code>object</code>:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">object</span><span class="token operator">&lt;</span><span class="token class-name">Translatable</span><span class="token punctuation">,</span> <span class="token class-name">Printable</span><span class="token operator">&gt;</span> <span class="token class-name">Point</span> <span class="token punctuation">{</span>
    x<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">,</span>
    y<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">,</span>

    <span class="token keyword">mut</span> <span class="token keyword">fun</span> <span class="token function-definition function">translate</span><span class="token punctuation">(</span>dx<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">,</span> dy<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
        <span class="token this constant">this</span><span class="token punctuation">.</span>x <span class="token operator">=</span> <span class="token this constant">this</span><span class="token punctuation">.</span>x <span class="token operator">+</span> dx<span class="token punctuation">;</span>
        <span class="token this constant">this</span><span class="token punctuation">.</span>y <span class="token operator">=</span> <span class="token this constant">this</span><span class="token punctuation">.</span>y <span class="token operator">+</span> dy<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">fun</span> <span class="token function-definition function">print</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
        <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">Point (</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span><span class="token this constant">this</span><span class="token punctuation">.</span>x<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">, </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span><span class="token this constant">this</span><span class="token punctuation">.</span>y<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">)</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token keyword">object</span><span class="token operator">&lt;</span><span class="token class-name">Printable</span><span class="token operator">&gt;</span> <span class="token class-name">Line</span> <span class="token punctuation">{</span>
    start<span class="token punctuation">:</span> <span class="token class-name">Point</span><span class="token punctuation">,</span>
    end<span class="token punctuation">:</span> <span class="token class-name">Point</span><span class="token punctuation">,</span>

    <span class="token keyword">fun</span> <span class="token function-definition function">print</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
        <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">Line (</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span><span class="token this constant">this</span><span class="token punctuation">.</span>start<span class="token punctuation">.</span>x<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">, </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span><span class="token this constant">this</span><span class="token punctuation">.</span>start<span class="token punctuation">.</span>y<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">) (</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span><span class="token this constant">this</span><span class="token punctuation">.</span>end<span class="token punctuation">.</span>x<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">, </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span><span class="token this constant">this</span><span class="token punctuation">.</span>end<span class="token punctuation">.</span>y<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">)</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Each listed protocol method must be implemented by the object. If a required method is missing, the compiler reports it.</p><p>Protocol methods can be regular methods, <code>mut</code> methods, and methods that can raise errors. What matters is that the object provides the required signature.</p><p>Once a value conforms to a protocol, that protocol can be used like any other type: it can be stored in variables, passed as a method parameter, and placed in heterogeneous collections such as <code>[Printable]</code> or maps whose keys or values are protocol-typed. When you need the concrete object back, you can downcast a protocol value with <code>value as? T</code>, <code>value as! T</code>, or <code>if (value as concrete: T)</code>.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token comment">// A protocol can be used directly in a parameter type.</span>
<span class="token keyword">fun</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span>shape<span class="token punctuation">:</span> <span class="token class-name">Printable</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
    shape<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// A concrete object can be stored behind the protocol type.</span>
<span class="token keyword">final</span> <span class="token variable">point</span><span class="token punctuation">:</span> <span class="token class-name">Printable</span> <span class="token operator">=</span> <span class="token class-name">Point</span><span class="token punctuation">{</span> x <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token comment">// Different concrete types can share the same collection.</span>
<span class="token keyword">final</span> <span class="token variable">shapes</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token class-name">Printable</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    point<span class="token punctuation">,</span>
    <span class="token class-name">Line</span><span class="token punctuation">{</span>
        start <span class="token operator">=</span> <span class="token class-name">Point</span><span class="token punctuation">{</span> x <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
        end <span class="token operator">=</span> <span class="token class-name">Point</span><span class="token punctuation">{</span> x <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">4</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token function">render</span><span class="token punctuation">(</span>point<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// \`as?\` returns \`null\` if the value is not a \`Point\`.</span>
<span class="token keyword">final</span> <span class="token variable">maybePoint</span> <span class="token operator">=</span> point <span class="token keyword">as?</span> <span class="token class-name">Point</span><span class="token punctuation">;</span>
<span class="token comment">// \`as!\` assumes the value is a \`Point\` and raises an error otherwise.</span>
<span class="token keyword">final</span> <span class="token variable">forcedPoint</span> <span class="token operator">=</span> point <span class="token keyword">as</span><span class="token operator">!</span> <span class="token class-name">Point</span><span class="token punctuation">;</span>

<span class="token comment">// \`if (value as name: T)\` downcasts and binds the concrete value.</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>point <span class="token keyword">as</span> concrete<span class="token punctuation">:</span> <span class="token class-name">Point</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span>concrete<span class="token punctuation">.</span>x<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">, </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span>concrete<span class="token punctuation">.</span>y<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,13),e=[p];function c(l,i){return s(),a("div",null,e)}const k=n(o,[["render",c],["__file","protocols.html.vue"]]);export{k as default};
